package ru.kryuch.krtg.searcher.helper;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Component;import ru.kryuch.krtg.searcher.config.SettingConfig;import ru.kryuch.krtg.searcher.dto.SendMessageParam;import ru.kryuch.krtg.searcher.entity.ChatEntity;import ru.kryuch.krtg.searcher.entity.FolderEntity;import ru.kryuch.krtg.searcher.integration.dto.ChatResponse;import ru.kryuch.krtg.searcher.integration.dto.FolderChatIdsRequestItem;import ru.kryuch.krtg.searcher.integration.dto.UpdateFolderRequest;import ru.kryuch.krtg.searcher.integration.tg.TelegramPythonClient;import ru.kryuch.krtg.searcher.repository.ChatRepository;import ru.kryuch.krtg.searcher.repository.FolderRepository;import ru.kryuch.krtg.searcher.service.FolderChatService;import ru.kryuch.krtg.searcher.service.SettingService;import ru.kryuch.krtg.searcher.util.SendResponse;import ru.kryuch.krtg.searcher.util.SendResult;import javax.swing.text.html.Option;import java.util.List;import java.util.Map;import java.util.Optional;import java.util.Set;import java.util.function.Function;import java.util.stream.Collectors;import java.util.stream.StreamSupport;@Component@RequiredArgsConstructor@Slf4jpublic class FolderHelper {    private final SettingService settingService;    private final FolderRepository folderRepository;    private final FolderChatService folderChatService;    public Map<Integer, FolderEntity> getFolderMap(List<Integer> folderIds) {        return StreamSupport.stream(                        folderRepository.findAllById(folderIds).spliterator(),                        false                )                .collect(Collectors.toMap(                        FolderEntity::getId,                        Function.identity()                ));    }    public void setToFolderAfterSending(SendMessageParam sendMessageParam, List<ChatResponse> chatDtos) {        if ("1".equals(settingService.getValueByCode(SettingConfig.FOLDER_ENABLE_SETTING_CODE)) && "1".equals(settingService.getValueByCode(SettingConfig.FOLDER_ADDING_SETTING_CODE))) {            List<Long> userIds =                    chatDtos.stream()                            .filter(item -> "success".equals(item.getStatus()))                            .map(ChatResponse::getId).toList();            folderChatService.updateLinksToTarget(userIds, sendMessageParam.getTgAccountId(), true);        }    }}